#!/usr/bin/env python3
"""Generate firmware/mearm_ik/config.h from config/arm.json (--check for CI)."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "firmware" / "mearm_ik" / "config.h"


def render(c):
    g, j, k, m = c["geometry"], c["joints"], c["linkage"], c["motion"]
    lines = [
        "// Generated by tools/gen_firmware_config.py from config/arm.json. Do not edit by hand.",
        "#pragma once",
        "",
        f"#define ARM_L1 {g['upper_arm_mm']:.3f}f",
        f"#define ARM_L2 {g['forearm_mm']:.3f}f",
        f"#define ARM_L3 {g['gripper_offset_mm']:.3f}f",
        "",
    ]
    for name in ("base", "shoulder", "elbow"):
        J = j[name]; N = name.upper()
        lines += [
            f"#define ARM_{N}_PIN {J['pin']}",
            f"#define ARM_{N}_CENTER {J['servo_center_deg']:.3f}f",
            f"#define ARM_{N}_SIGN {J['sign']:.1f}f",
            f"#define ARM_{N}_MIN {J['min_deg']:.3f}f",
            f"#define ARM_{N}_MAX {J['max_deg']:.3f}f",
        ]
    lines += [
        f"#define ARM_GRIPPER_PIN {j['gripper']['pin']}",
        f"#define ARM_GRIPPER_OPEN {j['gripper']['open_deg']}",
        f"#define ARM_GRIPPER_CLOSED {j['gripper']['closed_deg']}",
        "",
        f"#define ARM_INTERIOR_MIN {k['min_elbow_interior_deg']:.3f}f",
        f"#define ARM_INTERIOR_MAX {k['max_elbow_interior_deg']:.3f}f",
        "",
        f"#define ARM_SPEED_MM_S {m['cartesian_speed_mm_s']:.3f}f",
        f"#define ARM_STEP_MM {m['step_mm']:.3f}f",
        f"#define ARM_SETTLE_MS {m['settle_ms']}",
        f"#define ARM_HOME_X {m['home_mm'][0]:.3f}f",
        f"#define ARM_HOME_Y {m['home_mm'][1]:.3f}f",
        f"#define ARM_HOME_Z {m['home_mm'][2]:.3f}f",
        "",
    ]
    return "\n".join(lines)


if __name__ == "__main__":
    text = render(json.loads((ROOT / "config" / "arm.json").read_text()))
    if "--check" in sys.argv:
        ok = OUT.exists() and OUT.read_text() == text
        print("config.h is up to date" if ok else "config.h is stale; run tools/gen_firmware_config.py")
        sys.exit(0 if ok else 1)
    OUT.write_text(text)
    print("wrote", OUT.relative_to(ROOT))
